        public val letterSpacing: Float,
    )

    /** The type scale. */
    public object Typography {
        /** `display`: Audience name on landing, onboarding and sign-in. One per page. */
        public val display: TypeStyle = TypeStyle("Figtree", 32f, 36f, 800, -0.02f)
        /** `title`: Page titles and the AudienceHeader name. */
        public val title: TypeStyle = TypeStyle("Figtree", 24f, 28f, 700, -0.01f)
        /** `heading`: Card titles and section headings. */
        public val heading: TypeStyle = TypeStyle("Figtree", 17f, 22f, 700, 0f)
        /** `subheading`: List item titles, names in rows. */
        public val subheading: TypeStyle = TypeStyle("Figtree", 15f, 20f, 600, 0f)
        /** `body`: Default text everywhere: paragraphs, field values, notices. */
        public val body: TypeStyle = TypeStyle("Figtree", 15f, 20f, 400, 0f)
        /** `body-sm`: Metadata, timestamps, helper text. */
        public val bodySm: TypeStyle = TypeStyle("Figtree", 13f, 16f, 400, 0f)
        /** `label`: Buttons, field labels, tabs. */
        public val label: TypeStyle = TypeStyle("Figtree", 15f, 20f, 600, 0f)
        /** `caption`: Overlines and date-tile months, in uppercase. Never for sentences. */
        public val caption: TypeStyle = TypeStyle("Figtree", 12f, 16f, 700, 0.04f)
    }
}
